#!/usr/bin/env python3
"""mathjax-macros.tex (generated by TSS Workflow)  ->  lwarp-mathjax.tex
Keeps only macros that can occur in formulas, wraps them in \\CustomizeMathJax.
Usage: python mathjax2lwarp.py mathjax-macros.tex lwarp-mathjax.tex"""
import re, sys
src, dst = sys.argv[1], sys.argv[2]
# --- edit here ---------------------------------------------------------------
OVERRIDES = {
    'nfrac': r'\newcommand{\nfrac}[2]{{}^{#1}\!/{}_{#2}}',   # print = bold upright vectors (\symbf), so MathJax gets \mathbf, not \vec
    'vect': r'\newcommand{\vect}[1]{\mathbf{#1}}',
}
RENEW = {'phi', 'epsilon', 'iint', 'iiint'}        # already defined in MathJax

# Macros that MathJax must always have, even if mathjax-macros.tex lacks them or defines them in a way MathJax cannot read.
# \emf (package emf) is \mathemf{E} in LaTeX: a calligraphic E in the BOONDOX-cal alphabet; MathJax has no such alphabet.
ALWAYS = {'emf': r'\newcommand{\emf}{\mathcal{E}}'}

# Math operators that come from babel (Ukrainian/Russian), not from the class, so mathjax-macros.tex does not have them.
BABEL_OPS = [('sh', 'sh'), ('ch', 'ch'), ('tg', 'tg'), ('ctg', 'ctg'), ('arctg', 'arctg'), ('arcctg', 'arcctg'), ('cth', 'cth'), ('cosec', 'cosec')]
DENY = {'defcolor','sfdefault','bfdefault','MakeUppercase','title','cleardoublepage',
        'oldthebibliography','bibname','textflush','quizbadge','chapterautorefname',
        'emphx','symbfscr'}
MATHISH = re.compile(
    r'\\(frac|partial|vec|boldsymbol|mathbf|mathcal|mathbb|mathrm|nabla|int|oint|'
    r'Delta|varDelta|varphi|varepsilon|boxed|times|cdot|operatorname|square|mdlgwhtsquare)\b'
    r'|^\\(DeclareMathOperator)'
)
# -----------------------------------------------------------------------------
kept, dropped = [], []
for line in open(src, encoding='utf8'):
    s = line.strip()
    if not s or s.startswith('%'): continue
    m = re.match(r'\\(newcommand|DeclareMathOperator|let)\s*\{?\\([A-Za-z]+)\}?', s)
    if not m: dropped.append((s, 'unrecognised')); continue
    kind, name = m.groups()
    if name in DENY or re.search(r'\\(tl_|RequirePackage|tikz)', s):
        dropped.append((s, 'not math')); continue
    if name in OVERRIDES:
        kept.append(OVERRIDES[name]); continue
    if kind != 'DeclareMathOperator' and not MATHISH.search(s):
        dropped.append((s, 'no math content')); continue
    s = re.sub(r'\\vec\{(\w)\}', r'\\vect{\1}', s)    # \Efield -> \vect{E}
    if kind == 'newcommand' and name in RENEW: s = s.replace(r'\newcommand', r'\renewcommand', 1)
    kept.append(s)
defined = set(re.findall(r'\\(?:newcommand|renewcommand|DeclareMathOperator)\{\\([A-Za-z]+)\}', ' '.join(kept)))
for name, text in ALWAYS.items():
    if name not in defined: kept.append(text); defined.add(name)
for name, text in BABEL_OPS:
    if name not in defined: kept.append('\\DeclareMathOperator{\\%s}{%s}' % (name, text))
with open(dst, 'w', encoding='utf8') as f:
    f.write('%% Generated by mathjax2lwarp.py from %s. Do not edit by hand.\n' % src)
    f.write('\\begin{warpHTML}\n')
    for s in kept: f.write('\\CustomizeMathJax{%s}\n' % s)
    f.write('\\end{warpHTML}\n')
print('kept %d, dropped %d' % (len(kept), len(dropped)), file=sys.stderr)
for s, why in dropped: print('  dropped (%s): %s' % (why, s[:70]), file=sys.stderr)
